        {
            <div class="validation-summary">@_error</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @(_isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

