{"path": "/tmp/sv-e3cbd8b217934d2e825089f63b2ce2ae/Components/Application/ReviewStep.razor", "file_text": "@namespace sv_e3cbd8b217934d2e825089f63b2ce2ae.Components.Application

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (_submitted)
    {
        <div class="confirmation-card">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is <strong>@_applicationId</strong>.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-details">
                <dt>Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />@r.Email | @r.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="validation-summary">@_error</div>
        }

        <div class="step-actions">
            <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @(_isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> OnSubmit { get; set; } = default!;

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _error;

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        _error = null;
        try
        {
            _applicationId = await OnSubmit();
            _submitted = true;
        }
        catch (Exception ex)
        {
            _error = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}
"}

